def map_name_from_track(track: str) -> str:
    """Return the map portion from a 'Map - Track' Gauntlet route name."""
    return track.split(" - ", 1)[0].strip()

def map_icon_file(track: str, index: int = 0):
    """Create a Discord attachment for the supplied route's map icon, if available."""
    map_name = map_name_from_track(track)
    encoded = ALU_MAP_ICONS.get(map_name)
    if not encoded:
        return None, None
    safe = re.sub(r"[^a-z0-9]+", "_", map_name.lower()).strip("_") or "map"
    filename = f"map_icon_{safe}_{index}.png"
    return discord.File(fp=io.BytesIO(base64.b64decode(encoded)), filename=filename), filename

def map_preview_file(track: str, index: int = 0):
    """Create a Discord attachment for the supplied map's full preview image, if available."""
    map_name = map_name_from_track(track)
    asset = ALU_MAP_IMAGES.get(map_name)
    if not asset:
        return None, None
    ext = asset.get('ext', 'png')
    safe = re.sub(r"[^a-z0-9]+", "_", map_name.lower()).strip("_") or "map"
    filename = f"map_{safe}_{index}.{ext}"
    return discord.File(fp=io.BytesIO(base64.b64decode(asset['data'])), filename=filename), filename

def add_map_preview(embed: discord.Embed, filename: str | None = None) -> discord.Embed:
    """Attach a full map preview image to the embed."""
    if filename:
        embed.set_image(url=f"attachment://{filename}")
    return embed

def add_map_icon(embed: discord.Embed, track: str, filename: str | None = None) -> discord.Embed:
    """Attach the route's map icon as an embed thumbnail when an icon is available."""
    if filename:
        embed.set_thumbnail(url=f"attachment://{filename}")
    return embed

def get_car_rank_total(courses: list) -> int:
    """Return the total numeric performance/rating value of the cars in a defense."""
    return sum(int(course.get("car_rank", 0) or 0) for course in courses)

def build_course_embeds(courses: list, title: str, description: str = None, color: int = ASPHALT_THEME_COLOR):
    """Build one icon-backed embed per course and the corresponding Discord files."""
    embeds = []
    files = []
    if title:
        embeds.append(discord.Embed(title=title, description=description, color=color))
    for i, course in enumerate(courses):
        track = course.get("track", "Unknown Track")
        emb = discord.Embed(
            title=f"🏁 Course {i + 1}: {track}",
            description=(
                f"🚗 **Car:** `{course.get('car', 'TBD')}`\n"
                f"📈 **Car Performance:** `{course.get('car_rank', 'TBD')}`\n"
                f"⏱️ **Lap Time:** `{course.get('lap_time', 'TBD')}`"
            ),
            color=color,
        )
        icon_file, filename = map_icon_file(track, i)
        if icon_file:
            files.append(icon_file)
            add_map_icon(emb, track, filename)
        if course.get("proof_url"):
            emb.set_image(url=course["proof_url"])
        embeds.append(emb)
    return embeds, files

