@bot.tree.command(name="dbcheck", description="[Staff Only] Audits database consistency and recoverable settlement states.")
async def dbcheck_cmd(interaction: discord.Interaction):
    if not await check_admin_privileges(interaction):
        await interaction.response.send_message("❌ Access Denied: Admin authorization required.", ephemeral=True)
        return

    await interaction.response.defer(ephemeral=True)
    guild_id = str(interaction.guild.id) if interaction.guild else None
    if not guild_id:
        await interaction.followup.send("❌ This command must be used inside a server.", ephemeral=True)
        return

    issues = []
    checks = []
    try:
        # Current-season driver sanity checks.
        drivers = await bot.db.drivers.find({"guild_id": guild_id}).to_list(length=5000)
        checks.append(f"Drivers scanned: {len(drivers)}")
        seen_ids = set()
        for d in drivers:
            if d.get("_id") in seen_ids:
                issues.append(f"Duplicate driver id: {d.get('_id')}")
            seen_ids.add(d.get("_id"))
            elo = d.get("elo", 1000)
            pi = d.get("garage_pi")
            if not isinstance(elo, (int, float)) or elo < 100:
                issues.append(f"Invalid ELO: {d.get('_id')} = {elo}")
            if pi is not None and (not isinstance(pi, (int, float)) or pi < 0):
                issues.append(f"Invalid PI: {d.get('_id')} = {pi}")

        # Active challenges: no challenger should have more than one unfinished challenge.
        active = await bot.db.active_challenges.find({"guild_id": guild_id, "status": {"$in": ["active", "processing"]}}).to_list(length=5000)
        checks.append(f"Unfinished challenges scanned: {len(active)}")
        by_challenger = {}
        for ch in active:
            by_challenger.setdefault(ch.get("challenger_id"), []).append(ch)
            if not ch.get("opponent_id"):
                issues.append(f"Challenge missing opponent: {ch.get('_id')}")
            if ch.get("status") == "active" and ch.get("expires_at") and float(ch.get("expires_at", 0)) <= time.time():
                issues.append(f"Expired active challenge: {ch.get('_id')}")
            if ch.get("status") in {"active", "processing"} and int(ch.get("season_number", 0)) <= 0:
                issues.append(f"Challenge missing season number: {ch.get('_id')}")
            if ch.get("status") == "processing" and ch.get("processing_at"):
                age = time.time() - float(ch.get("processing_at", time.time()))
                if age > 15 * 60:
                    issues.append(f"Stale processing challenge: {ch.get('_id')} ({int(age/60)}m)")
        for uid, rows in by_challenger.items():
            if len(rows) > 1:
                issues.append(f"Multiple unfinished challenges for {uid}: {len(rows)}")

        # Settlement reservations: completed rows must have matching driver ELOs; pending rows
        # are flagged for recovery review rather than silently modified by this audit command.
        matches = await bot.db.matches.find({"guild_id": guild_id}).to_list(length=5000)
        checks.append(f"Match settlements scanned: {len(matches)}")
        for m in matches:
            status = m.get("settlement_status")
            if status == "pending":
                issues.append(f"Pending settlement requires recovery review: {m.get('_id')}")
                continue
            if status == "completed" and m.get("challenger_elo_after") is not None and m.get("defender_elo_after") is not None:
                c = await bot.db.drivers.find_one({"_id": f"{guild_id}_{m.get('challenger_id')}"})
                d = await bot.db.drivers.find_one({"_id": f"{guild_id}_{m.get('opponent_id')}"})
                if c and d:
                    # A later match may legitimately change ELO, so only flag impossible missing drivers.
                    pass
                elif not c or not d:
                    issues.append(f"Completed match references missing driver(s): {m.get('_id')}")

        status_line = "✅ DATABASE CONSISTENT" if not issues else f"⚠️ {len(issues)} ISSUE(S) FOUND"
        embed = discord.Embed(title="🗄️ ALU GAUNTLET — DATABASE CHECK", description=status_line, color=ASPHALT_VICTORY_COLOR if not issues else ASPHALT_ADMIN_COLOR, timestamp=datetime.now(timezone.utc))
        embed.add_field(name="Checks", value="\n".join(f"• {x}" for x in checks) or "• No records found", inline=False)
        if issues:
            preview = "\n".join(f"• {x}" for x in issues[:20])
            if len(issues) > 20:
                preview += f"\n• …and {len(issues)-20} more"
            embed.add_field(name="Issues / Recovery Review", value=preview[:1024], inline=False)
        else:
            embed.add_field(name="Recovery Test", value="• Settlement reservations and challenge locks passed structural checks.\n• No automatic mutations were made.", inline=False)
        await interaction.followup.send(embed=embed, ephemeral=True)
        await audit_admin_action(interaction, "DBCheck", f"Database consistency audit: {len(issues)} issue(s).")
    except Exception as exc:
        logging.exception("Database consistency check failed", exc_info=exc)
        await interaction.followup.send(f"❌ Database consistency check failed: `{exc}`", ephemeral=True)

@bot.tree.command(name="seasonhistory", description="View archived final standings from completed seasons.")
@app_commands.describe(season="Season number to view (optional)")
async def seasonhistory_cmd(interaction: discord.Interaction, season: int = None):
    if not await enforce_channel_constraints(interaction, admin_cmd=False):
        return
    guild_id = str(interaction.guild_id)
    if season is not None:
        archive = await bot.db.season_history.find_one({"_id": f"{guild_id}_{int(season)}"})
        if not archive:
            await interaction.response.send_message(f"❌ No archived Season {int(season)} was found.", ephemeral=True)
            return
        rows = archive.get("standings", [])
        lines = []
        for row in rows[:25]:
            lines.append(f"**#{row.get('rank')}** <@{row.get('user_id')}> — **{row.get('elo',1000)} ELO** — {row.get('division','Unranked')}")
        desc = "\n".join(lines) if lines else "*No archived standings.*"
        if len(rows) > 25:
            desc += f"\n\n…and {len(rows)-25} more drivers in the archived record."
        embed = discord.Embed(title=f"🏆 SEASON {int(season)} ARCHIVE", description=desc[:4096], color=ASPHALT_THEME_COLOR)
        embed.set_footer(text=f"Closed {datetime.fromtimestamp(float(archive.get('closed_at', time.time())), tz=timezone.utc).strftime('%Y-%m-%d')}")
        await interaction.response.send_message(embed=embed, ephemeral=True)
        return
    archives = await bot.db.season_history.find({"guild_id": guild_id}).sort("season_number", -1).limit(15).to_list(length=15)
    if not archives:
        await interaction.response.send_message("ℹ️ No completed season archives yet.", ephemeral=True)
        return
    lines = [f"🏁 **Season {a.get('season_number')}** — `{a.get('player_count', len(a.get('standings', [])))}` drivers — {datetime.fromtimestamp(float(a.get('closed_at', time.time())), tz=timezone.utc).strftime('%Y-%m-%d')}" for a in archives]
    await interaction.response.send_message(embed=discord.Embed(title="🏆 SEASON ARCHIVES", description="\n".join(lines), color=ASPHALT_THEME_COLOR), ephemeral=True)

@bot.tree.command(name="backup", description="[Staff Only] Create an immediate database backup.")
async def backup_cmd(interaction: discord.Interaction):
    if not await check_admin_privileges(interaction):
        await interaction.response.send_message("❌ Staff only.", ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True)
    try:
        folder = await create_database_backup(f"manual by {interaction.user.id}")
        if folder:
            await interaction.followup.send(f"✅ Database backup created.\n`{folder}`", ephemeral=True)
            await audit_admin_action(interaction, "Database Backup", f"Created backup `{folder}`.")
        else:
            await interaction.followup.send("ℹ️ MongoDB is not connected; no cloud database backup was created.", ephemeral=True)
    except Exception as exc:
        logging.exception("Manual database backup failed")
        await interaction.followup.send(f"❌ Backup failed: `{exc}`", ephemeral=True)
        await send_admin_alert(str(interaction.guild_id), "DATABASE BACKUP FAILED", str(exc))

@bot.tree.command(name="diagnostics", description="[Staff Only] Run a read-only health and database diagnostic report.")
async def diagnostics_cmd(interaction: discord.Interaction):
    if not await check_admin_privileges(interaction):
        await interaction.response.send_message("❌ Staff only.", ephemeral=True)
        return

    await interaction.response.defer(ephemeral=True)
    guild_id = str(interaction.guild_id)
    now = time.time()
    uptime_seconds = max(0, int(now - getattr(bot, "started_at", now)))

    def fmt_uptime(seconds: int) -> str:
        days, rem = divmod(seconds, 86400)
        hours, rem = divmod(rem, 3600)
        minutes, secs = divmod(rem, 60)
        parts = []
        if days: parts.append(f"{days}d")
        if hours or days: parts.append(f"{hours}h")
        if minutes or hours or days: parts.append(f"{minutes}m")
        parts.append(f"{secs}s")
        return " ".join(parts)

    def task_status(task_obj) -> str:
        if task_obj is None:
            return "⚪ Not initialized"
        try:
            if task_obj.is_running():
                return "🟢 Running"
            if task_obj.is_being_cancelled():
                return "🟡 Stopping"
            if task_obj.failed():
                return "🔴 Failed"
        except Exception:
            pass
        return "⚪ Stopped"

    runtime = []
    counts = {}
    integrity = []
    mongo_ok = False

    latency = bot.latency
    latency_text = f"{round(latency * 1000, 1)}ms" if latency != float("inf") else "N/A"
    runtime.append(("Gateway", f"🟢 Online • {latency_text}"))
    runtime.append(("Uptime", f"🟢 {fmt_uptime(uptime_seconds)}"))
    runtime.append(("Commands", f"🟢 {len(bot.tree.get_commands())} loaded"))
    runtime.append(("Python", f"`{sys.version.split()[0]}`"))
    runtime.append(("Host", f"`{platform.system()}`"))

    try:
        if bot.mongo_client:
            started = time.perf_counter()
            await bot.mongo_client.admin.command("ping")
            mongo_ms = round((time.perf_counter() - started) * 1000, 1)
            mongo_ok = True
            runtime.append(("MongoDB", f"🟢 Connected • {mongo_ms}ms"))
            for name in ("drivers", "pending", "matches", "active_challenges", "season_history", "reference_pending"):
                try:
                    counts[name] = await getattr(bot.db, name).count_documents({})
                except Exception:
                    counts[name] = "?"
            try:
                meta = await bot.db.settings.find_one({"_id": "global_meta"})
                if meta and meta.get("guild_overrides_cleaned"):
                    runtime.append(("Guild Command Overrides", "🟢 Cleared (cached — skipped on future boots)"))
                else:
                    runtime.append(("Guild Command Overrides", "🟡 Not yet cleared — will run on next boot, or use `/sync full_cleanup:True`"))
            except Exception:
                runtime.append(("Guild Command Overrides", "🔴 Could not check status"))
        else:
            runtime.append(("MongoDB", "🔴 Not connected • mock DB active"))
    except Exception as exc:
        runtime.append(("MongoDB", f"🔴 Error • {str(exc)[:160]}"))

    season_text = "Unavailable"
    queue_text = "Unavailable"
    if mongo_ok:
        try:
            state = await bot.db.season_state.find_one({"_id": f"guild_{guild_id}"})
            season = int(state.get("season_number", 1)) if state else 1
            registered = await bot.db.drivers.count_documents({"guild_id": guild_id, "season_registered": True, "season_number": season})
            pending = await bot.db.pending.count_documents({"guild_id": guild_id, "season_number": season})
            active = await bot.db.active_challenges.count_documents({"guild_id": guild_id, "status": {"$in": ["active", "processing"]}})
            stale = await bot.db.active_challenges.count_documents({"guild_id": guild_id, "status": "processing", "processing_at": {"$lt": now - 900}})
            pending_settlements = await bot.db.matches.count_documents({"guild_id": guild_id, "settlement_status": "pending"})
            bad_elo = await bot.db.drivers.count_documents({"guild_id": guild_id, "$or": [{"elo": {"$lt": 0}}, {"elo": {"$gt": 10000}}]})
            bad_pi = await bot.db.drivers.count_documents({"guild_id": guild_id, "$or": [{"garage_pi": {"$lt": 0}}, {"garage_pi": {"$gt": 100000}}]})
            season_text = f"Season {season} • {registered} registered"
            queue_text = f"{active} active/processing • {pending} pending"
            if stale:
                integrity.append(f"⚠️ Stale processing challenges: `{stale}`")
            if pending_settlements:
                integrity.append(f"⚠️ Pending settlements: `{pending_settlements}`")
            if bad_elo:
                integrity.append(f"⚠️ Invalid ELO records: `{bad_elo}`")
            if bad_pi:
                integrity.append(f"⚠️ Invalid PI records: `{bad_pi}`")
            if not integrity:
                integrity.append("🟢 No obvious integrity issues found")
        except Exception as exc:
            integrity.append(f"🔴 Integrity check failed: {str(exc)[:160]}")
    else:
        integrity.append("🔴 Database integrity checks skipped — MongoDB unavailable")

    task_lines = [
        f"**Season Clock:** {task_status(getattr(bot, 'seasonal_clock_loop', None))}",
        f"**Player Reminders:** {task_status(getattr(bot, 'player_reminder_loop', None))}",
        f"**Backups:** {task_status(getattr(bot, 'backup_loop', None))}",
    ]

    backup_root = os.getenv("BACKUP_DIR", "./backups")
    backup_text = "⚪ No local backup directory"
    try:
        if os.path.isdir(backup_root):
            folders = [os.path.join(backup_root, x) for x in os.listdir(backup_root) if os.path.isdir(os.path.join(backup_root, x))]
            folders.sort(key=lambda x: os.path.getmtime(x), reverse=True)
            if folders:
                age_hours = max(0, (now - os.path.getmtime(folders[0])) / 3600)
                status = "🟢" if age_hours <= 30 else "🟡" if age_hours <= 48 else "🔴"
                backup_text = f"{status} {len(folders)} local • latest {age_hours:.1f}h ago"
            else:
                backup_text = "🔴 No local backups found"
    except Exception as exc:
        backup_text = f"🔴 Check failed • {str(exc)[:100]}"

    embed = discord.Embed(
        title="🛠️ ALU GAUNTLET — DIAGNOSTICS",
        description="Read-only system, database, task, and backup health check.",
        color=ASPHALT_ADMIN_COLOR if mongo_ok else ASPHALT_ALERT_COLOR,
        timestamp=datetime.now(timezone.utc),
    )
    embed.set_thumbnail(url=ASPHALT_MEDIA["thumb_diagnostics"])
    embed.add_field(name="🖥️ Runtime", value="\n".join(f"**{k}:** {v}" for k, v in runtime), inline=False)
    embed.add_field(name="🗄️ Database", value="\n".join([
        f"**Drivers:** `{counts.get('drivers', '?')}`",
        f"**Pending:** `{counts.get('pending', '?')}`",
        f"**Matches:** `{counts.get('matches', '?')}`",
        f"**Challenges:** `{counts.get('active_challenges', '?')}`",
        f"**Season Archives:** `{counts.get('season_history', '?')}`",
        f"**Reference Queue:** `{counts.get('reference_pending', '?')}`",
    ]), inline=True)
    embed.add_field(name="⚙️ Tasks & Backups", value="\n".join(task_lines) + f"\n**Local Backups:** {backup_text}", inline=True)
    embed.add_field(name="🏁 League", value=f"**Current:** {season_text}\n**Queue:** {queue_text}", inline=False)
    embed.add_field(name="🔍 Integrity", value="\n".join(integrity)[:1024], inline=False)
    embed.set_footer(text="Read-only • /dbcheck = full audit • /backup = manual backup")

    await interaction.followup.send(embed=embed, ephemeral=True)
    await audit_admin_action(interaction, "Diagnostics", "Ran read-only system, database, task, and backup diagnostics.")

@bot.tree.error
async def on_app_command_error(interaction: discord.Interaction, error: app_commands.AppCommandError):
    logging.exception("Application command error", exc_info=error)
    try:
        if not interaction.response.is_done():
            await interaction.response.send_message("❌ An unexpected bot error occurred. Staff have been alerted.", ephemeral=True)
        else:
            await interaction.followup.send("❌ An unexpected bot error occurred. Staff have been alerted.", ephemeral=True)
    except Exception:
        pass
    if interaction.guild_id:
        await send_admin_alert(str(interaction.guild_id), "BOT COMMAND ERROR", f"Command: `/{getattr(interaction.command, 'name', 'unknown')}`\nError: `{error}`")

@bot.event
async def on_guild_join(guild: discord.Guild):
    """Immediately remove any stale guild-scoped command overrides in a newly joined server."""
    try:
        logging.info("🔄 Joined %s (%s); cleaning stale guild-scoped commands.", guild.name, guild.id)
        await bot.sync_guild_application_commands(force_fetch=False)
        if bot._guild_cleanup_failed:
            logging.error("🔴 New-server command cleanup could not be verified for %s (%s).", guild.name, guild.id)
        else:
            logging.info("🟢 New-server command cleanup verified for %s (%s).", guild.name, guild.id)
    except Exception:
        logging.exception("🔴 New-server command cleanup failed for %s (%s).", guild.name, guild.id)


@bot.event
async def on_ready():
    """Fallback: remove stale guild-scoped command overrides if the setup_hook
    attempt couldn't run (e.g. the guild cache was still empty at that point).
    Skips entirely once the cleanup has already completed, so reconnects and
    Discloud auto-redeploys don't repeatedly hammer Discord's per-guild sync
    endpoint."""
    try:
        meta = await bot.db.settings.find_one({"_id": "global_meta"})
        if meta and meta.get("guild_overrides_cleaned"):
            return
    except Exception:
        logging.exception("🔴 Could not check guild command override cleanup status.")
        return

    logging.info("🔄 Discord READY received; starting server-scoped command cleanup.")

    # Discord may populate the guild cache just after READY. Retry briefly so the
    # cleanup is performed against the actual guild list instead of an empty cache.
    for attempt in range(1, 4):
        try:
            if not bot.guilds:
                logging.warning("⚠️ Server command cleanup attempt %d/3: guild cache is empty; retrying.", attempt)
                await asyncio.sleep(3)
                continue

            cleaned = await bot.sync_guild_application_commands(force_fetch=not bool(bot.guilds))
            if not bot._guild_cleanup_failed:
                await bot.db.settings.update_one({"_id": "global_meta"}, {"$set": {"guild_overrides_cleaned": True}}, upsert=True)
                logging.info(
                    "🟢 GUILD COMMAND OVERRIDE CLEANUP COMPLETE — %d server command(s) synchronized and verified.",
                    cleaned,
                )
                return
            logging.error("🔴 Guild command cleanup attempt %d was incomplete; completion flag remains unset.", attempt)
        except Exception:
            logging.exception("🔴 Server command cleanup attempt %d/3 failed.", attempt)
            await asyncio.sleep(3)

    logging.error("🔴 GUILD COMMAND OVERRIDE CLEANUP FAILED after 3 attempts.")

@bot.event
async def on_error(event_method, *args, **kwargs):
    logging.exception("Unhandled Discord event error: %s", event_method)
    for cfg in await bot.db.settings.find({}).to_list(length=1000):
        await send_admin_alert(str(cfg.get("_id")), "BOT EVENT ERROR", f"Event: `{event_method}`")

if __name__ == "__main__":
    token = os.getenv("DISCORD_BOT_TOKEN")
    if not token:
        raise RuntimeError("DISCORD_BOT_TOKEN is required in production")
    bot.run(token)
